package com.waldron.adventurerspack;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.projectile.*;
import net.minecraft.world.entity.EntityType;
@GameTestHolder(AdventurersPack.ID)
@PrefixGameTestTemplate(false)
public class BowArtsTests {
 private static net.minecraft.world.entity.player.Player archer(GameTestHelper h,int form){var p=h.makeMockPlayer();p.getAbilities().instabuild=false;p.setPos(h.absolutePos(new net.minecraft.core.BlockPos(1,20,1)).getCenter());p.setYRot(0);p.setXRot(0);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Requiem.item(form)));p.getInventory().setItem(9,new ItemStack(Items.ARROW,8));p.startUsingItem(InteractionHand.MAIN_HAND);return p;}
 @GameTest(template="empty") public static void spreadConsumesOne(GameTestHelper h){var p=archer(h,2);var bow=(RequiemBowItem)p.getMainHandItem().getItem();var before=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));bow.releaseUsing(p.getMainHandItem(),h.getLevel(),p,71988);var shots=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));shots.removeAll(before);h.assertTrue(shots.size()==3,"Full charge creates three arrows");h.assertTrue(shots.stream().filter(a->a.pickup==AbstractArrow.Pickup.ALLOWED).count()==1&&shots.stream().filter(a->a.pickup==AbstractArrow.Pickup.DISALLOWED).count()==2,"Only consumed arrow is recoverable");double min=shots.stream().mapToDouble(a->a.getDeltaMovement().x).min().getAsDouble(),max=shots.stream().mapToDouble(a->a.getDeltaMovement().x).max().getAsDouble();h.assertTrue(max-min>.6,"Distinct spread trajectories");h.assertTrue(p.getInventory().getItem(9).getCount()==7&&p.getMainHandItem().getDamageValue()==0,"One arrow per volley and the bow stays unworn");shots.forEach(a->a.discard());h.succeed();}
 @GameTest(template="empty") public static void partialChargeSingleShot(GameTestHelper h){var p=archer(h,2);var before=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));((RequiemBowItem)p.getMainHandItem().getItem()).releaseUsing(p.getMainHandItem(),h.getLevel(),p,71994);var shots=h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(3));shots.removeAll(before);h.assertTrue(shots.size()==1,"Partial charge fires one arrow");shots.forEach(a->a.discard());h.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void recurveHitsTwoTargets(GameTestHelper h){var p=archer(h,3);var first=EntityType.COW.create(h.getLevel());var second=EntityType.COW.create(h.getLevel());first.setNoAi(true);second.setNoAi(true);first.setNoGravity(true);second.setNoGravity(true);first.setPos(p.getX(),p.getY()+.5,p.getZ()+4);second.setPos(p.getX(),p.getY()+.5,p.getZ()+8);h.getLevel().addFreshEntity(first);h.getLevel().addFreshEntity(second);((RequiemBowItem)p.getMainHandItem().getItem()).releaseUsing(p.getMainHandItem(),h.getLevel(),p,71980);h.succeedWhen(()->{h.assertTrue(first.getHealth()<first.getMaxHealth()&&second.getHealth()<second.getMaxHealth(),"One piercing projectile damages both enemies");first.discard();second.discard();h.getLevel().getEntitiesOfClass(AbstractArrow.class,p.getBoundingBox().inflate(15)).forEach(a->a.discard());});}
 @GameTest(template="empty") public static void heavyKnockbackStacks(GameTestHelper h){var p=archer(h,4);var w=p.getMainHandItem();w.enchant(Enchantments.PUNCH_ARROWS,2);var bow=(RequiemBowItem)w.getItem();var full=bow.createShot(h.getLevel(),p,w,new ItemStack(Items.ARROW),1,0,false,false);var partial=bow.createShot(h.getLevel(),p,w,new ItemStack(Items.ARROW),.5f,0,false,false);h.assertTrue(full.getKnockback()==5&&partial.getKnockback()==2,"Charged greatbow adds three knockback levels to Punch");h.succeed();}
 @GameTest(template="empty") public static void spectralPiercing(GameTestHelper h){var p=archer(h,3);var bow=(RequiemBowItem)p.getMainHandItem().getItem();var full=bow.createShot(h.getLevel(),p,p.getMainHandItem(),new ItemStack(Items.SPECTRAL_ARROW),1,0,false,false);var partial=bow.createShot(h.getLevel(),p,p.getMainHandItem(),new ItemStack(Items.ARROW),.5f,0,false,false);h.assertTrue(full instanceof SpectralArrow&&full.getPierceLevel()==2,"Full draw supports spectral arrows and three-target piercing");h.assertTrue(partial.getPierceLevel()==0,"Partial shots do not pierce");h.succeed();}
}
